package com.thangit.boardinghouse.service;

import com.thangit.boardinghouse.common.exception.AuthException;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.repository.*;
import com.thangit.boardinghouse.security.*;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ManagementFinanceService {
 public record Decision(@PositiveOrZero long version,@NotBlank @Size(max=1000) String reason){}
 public record PayVoucher(@PositiveOrZero long version,@NotNull LocalDateTime paidAt,@NotBlank @Size(max=100) String reference,@NotBlank @Size(max=500) String evidence){}
 public record PeriodCreate(@NotNull @Positive Long propertyId,@NotBlank @Pattern(regexp="[1-9][0-9]{3}-(0[1-9]|1[0-2])") String period){}
 private final JdbcClient db;private final ManagementFinanceRepository finance;private final PropertyAuthorization authorization;
 public ManagementFinanceService(JdbcClient db,ManagementFinanceRepository finance,PropertyAuthorization authorization){this.db=db;this.finance=finance;this.authorization=authorization;}
 public List<Long> scope(AuthenticatedUser p,Long property){
  if(p==null||!Set.of(RoleCode.OWNER,RoleCode.MANAGER,RoleCode.ACCOUNTANT).contains(p.activeRole()))throw denied();
  String where=switch(p.activeRole()){case OWNER->"p.owner_id=:user";case MANAGER->"EXISTS(SELECT 1 FROM property_managers m JOIN manager_property_capabilities c ON c.manager_id=m.manager_id AND c.property_id=m.property_id WHERE m.manager_id=:user AND m.property_id=p.id AND c.capability='FINANCE_READ')";default->"EXISTS(SELECT 1 FROM accountant_property_assignments a WHERE a.accountant_id=:user AND a.property_id=p.id) AND EXISTS(SELECT 1 FROM accountant_profiles ap WHERE ap.user_id=:user)";};
  var ids=db.sql("SELECT p.id FROM properties p WHERE "+where).param("user",p.id()).query(Long.class).list();if(property!=null&&!ids.contains(property))throw denied();return property==null?ids:List.of(property);
 }
 @Transactional(readOnly=true) public Map<String,Object> report(AuthenticatedUser p,Long property,LocalDate start,LocalDate end){dates(start,end);var ids=scope(p,property);var result=new LinkedHashMap<String,Object>();result.put("policy","INTERNAL_CASH_MANAGEMENT_V1");result.put("recognizedRevenueSupported",false);result.put("accountingProfitSupported",false);result.put("propertyIds",ids);result.put("startDate",start);result.put("endDate",end);result.put("balanceAsOf",LocalDateTime.now());result.put("summary",finance.summary(ids,start,end));result.put("trend",finance.trend(ids,start,end));result.put("generatedAt",LocalDateTime.now());return result;}
 @Transactional(readOnly=true) public List<Map<String,Object>> cash(AuthenticatedUser p,Long property,LocalDate start,LocalDate end){dates(start,end);return finance.cashEvents(scope(p,property),start,end);}
 @Transactional public Map<String,Object> approve(AuthenticatedUser p,long id,Decision r,boolean approved){var v=voucher(p,id);if(p.activeRole()!=RoleCode.OWNER||num(v,"created_by")==p.id())throw denied();open(num(v,"property_id"),date(v.get("voucher_date")));changed(db.sql("UPDATE payment_vouchers SET status=:status,approved_by=:actor,approved_at=NOW(6),version=version+1 WHERE id=:id AND version=:version AND status='PENDING_APPROVAL'").param("status",approved?"APPROVED":"REJECTED").param("actor",p.id()).param("id",id).param("version",r.version()).update());audit(p,v,approved?"APPROVED":"REJECTED",r.reason());return voucher(p,id);}
 @Transactional public Map<String,Object> pay(AuthenticatedUser p,long id,String key,PayVoucher r){
  if(key==null||key.isBlank()||key.length()>100)throw fail("IDEMPOTENCY_KEY_REQUIRED");var v=voucher(p,id);write(p,num(v,"property_id"));
  if("PAID".equals(v.get("status"))){if(key.equals(v.get("payment_key"))&&r.reference().trim().equals(v.get("payment_reference"))&&r.evidence().trim().equals(v.get("payment_evidence"))&&r.paidAt().withNano(r.paidAt().getNano()/1000*1000).equals(time(v.get("paid_at"))))return v;throw fail("VOUCHER_ALREADY_PAID");}
  if(r.paidAt().isAfter(LocalDateTime.now().plusMinutes(1)))throw fail("FUTURE_CASH_DATE");open(num(v,"property_id"),r.paidAt().toLocalDate());
  if(db.sql("SELECT COUNT(*) FROM payment_vouchers WHERE property_id=:property AND payment_method=:method AND payment_reference=:ref AND status IN ('PAID','REVERSED')").param("property",v.get("property_id")).param("method",v.get("payment_method")).param("ref",r.reference().trim()).query(Long.class).single()>0)throw fail("VOUCHER_REFERENCE_DUPLICATE");
  changed(db.sql("UPDATE payment_vouchers SET status='PAID',paid_at=:at,paid_by=:actor,payment_key=:key,payment_reference=:ref,payment_evidence=:evidence,version=version+1 WHERE id=:id AND status='APPROVED' AND version=:version AND approved_by IS NOT NULL AND approved_by<>created_by").param("at",r.paidAt()).param("actor",p.id()).param("key",key).param("ref",r.reference().trim()).param("evidence",r.evidence().trim()).param("id",id).param("version",r.version()).update());audit(p,v,"PAID",r.reference());return voucher(p,id);
 }
 @Transactional public Map<String,Object> reverse(AuthenticatedUser p,long id,Decision r){var v=voucher(p,id);if(p.activeRole()!=RoleCode.OWNER)throw denied();open(num(v,"property_id"),date(v.get("voucher_date")));open(num(v,"property_id"),time(v.get("paid_at")).toLocalDate());open(num(v,"property_id"),LocalDate.now());changed(db.sql("UPDATE payment_vouchers SET status='REVERSED',reversed_by=:actor,reversed_at=NOW(6),reversal_reason=:reason,version=version+1 WHERE id=:id AND version=:version AND status='PAID'").param("actor",p.id()).param("reason",r.reason()).param("id",id).param("version",r.version()).update());audit(p,v,"REVERSED",r.reason());return voucher(p,id);}
 private Map<String,Object> voucher(AuthenticatedUser p,long id){var v=db.sql("SELECT * FROM payment_vouchers WHERE id=:id FOR UPDATE").param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->fail("VOUCHER_NOT_FOUND"));scope(p,num(v,"property_id"));return v;}
 @Transactional(readOnly=true) public List<Map<String,Object>> vouchers(AuthenticatedUser p,Long property){var ids=scope(p,property);return db.sql("SELECT id,property_id,voucher_code,payee_name,amount,expense_category,voucher_date,status,version,created_by,approved_by,paid_at FROM payment_vouchers WHERE property_id IN (:ids) ORDER BY created_at DESC").param("ids",ids.isEmpty()?List.of(-1L):ids).query().listOfRows();}
 @Transactional public Map<String,Object> createPeriod(AuthenticatedUser p,PeriodCreate r){scope(p,r.propertyId());var accounts=new AccountantPortalRepository(db);if(p.activeRole()!=RoleCode.ACCOUNTANT||!accounts.permission(p.id(),"can_close_period"))throw denied();var month=YearMonth.parse(r.period());FinancialPeriodLocks.lock(db,r.propertyId());db.sql("INSERT INTO accounting_periods(property_id,period_code,start_date,end_date) VALUES(:property,:code,:start,:end) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)").param("property",r.propertyId()).param("code",r.period()).param("start",month.atDay(1)).param("end",month.atEndOfMonth()).update();var row=db.sql("SELECT * FROM accounting_periods WHERE property_id=:property AND period_code=:code").param("property",r.propertyId()).param("code",r.period()).query().singleRow();accounts.audit(r.propertyId(),p.id(),"ACCOUNTING_PERIOD",num(row,"id"),"OPEN_REQUESTED","Requested monthly accounting period; existing closed status is preserved.");return row;}
 private void write(AuthenticatedUser p,long property){if(p.activeRole()==RoleCode.MANAGER)authorization.require(p,property,PropertyAuthorization.Capability.FINANCE_WRITE);if(p.activeRole()==RoleCode.ACCOUNTANT&&!new AccountantPortalRepository(db).permission(p.id(),"can_record_payment"))throw denied();}
 @Transactional public Map<String,Object> attach(AuthenticatedUser p,long id,org.springframework.web.multipart.MultipartFile file){var v=voucher(p,id);write(p,num(v,"property_id"));if(file.isEmpty()||file.getSize()>5*1024*1024)throw fail("VOUCHER_FILE_INVALID");try{byte[] bytes=file.getBytes();String type=file.getContentType();boolean valid=("application/pdf".equals(type)&&bytes.length>4&&bytes[0]=='%'&&bytes[1]=='P'&&bytes[2]=='D'&&bytes[3]=='F')||("image/png".equals(type)&&bytes.length>7&&(bytes[0]&255)==137&&bytes[1]=='P'&&bytes[2]=='N'&&bytes[3]=='G')||("image/jpeg".equals(type)&&bytes.length>2&&(bytes[0]&255)==255&&(bytes[1]&255)==216&&(bytes[2]&255)==255);if(!valid)throw fail("VOUCHER_FILE_INVALID");String name=Objects.toString(file.getOriginalFilename(),"evidence").replaceAll("[\\\\/\\r\\n\\x00-\\x1F]","_");if(name.length()>200)name=name.substring(name.length()-200);var key=new org.springframework.jdbc.support.GeneratedKeyHolder();db.sql("INSERT INTO payment_voucher_documents(voucher_id,original_name,content_type,file_content,uploaded_by) VALUES(:voucher,:name,:type,:bytes,:actor)").param("voucher",id).param("name",name).param("type",type).param("bytes",bytes).param("actor",p.id()).update(key,"id");audit(p,v,"EVIDENCE_ATTACHED","document="+key.getKey());return Map.of("id",key.getKey().longValue(),"voucherId",id);}catch(java.io.IOException e){throw fail("VOUCHER_FILE_INVALID");}}
 @Transactional(readOnly=true) public List<Map<String,Object>> documents(AuthenticatedUser p,long id){var v=db.sql("SELECT property_id FROM payment_vouchers WHERE id=:id").param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->fail("VOUCHER_NOT_FOUND"));scope(p,num(v,"property_id"));return db.sql("SELECT id,original_name,content_type,uploaded_at FROM payment_voucher_documents WHERE voucher_id=:id ORDER BY id").param("id",id).query().listOfRows();}
 @Transactional(readOnly=true) public Map<String,Object> document(AuthenticatedUser p,long id,long document){documents(p,id);return db.sql("SELECT original_name,content_type,file_content FROM payment_voucher_documents WHERE voucher_id=:id AND id=:document").param("id",id).param("document",document).query().listOfRows().stream().findFirst().orElseThrow(()->fail("VOUCHER_DOCUMENT_NOT_FOUND"));}
 public void open(long property,LocalDate date){FinancialPeriodLocks.lock(db,property);db.sql("SELECT id FROM properties WHERE id=:id FOR UPDATE").param("id",property).query(Long.class).single();if(db.sql("SELECT id FROM accounting_periods WHERE property_id=:id AND status='CLOSED' AND :date BETWEEN start_date AND end_date FOR UPDATE").param("id",property).param("date",date).query(Long.class).list().size()>0)throw fail("ACCOUNTING_PERIOD_CLOSED");}
 private void audit(AuthenticatedUser p,Map<String,Object> v,String action,String reason){new AccountantPortalRepository(db).audit(num(v,"property_id"),p.id(),"PAYMENT_VOUCHER",num(v,"id"),action,reason);}
 private static long num(Map<String,Object> m,String k){return ((Number)m.get(k)).longValue();}
 private static LocalDate date(Object v){return v instanceof LocalDate d?d:((java.sql.Date)v).toLocalDate();}
 private static LocalDateTime time(Object v){if(v==null)throw fail("VOUCHER_NOT_PAID");return v instanceof LocalDateTime d?d:((java.sql.Timestamp)v).toLocalDateTime();}
 private static void dates(LocalDate s,LocalDate e){if(s==null||e==null||e.isBefore(s)||e.isAfter(s.plusYears(2)))throw fail("REPORT_DATE_RANGE_INVALID");}
 private static void changed(int n){if(n!=1)throw fail("VOUCHER_VERSION_OR_STATE_CONFLICT");}
 private static AuthException fail(String code){return new AuthException(code.endsWith("NOT_FOUND")?HttpStatus.NOT_FOUND:Set.of("VOUCHER_FILE_INVALID","FUTURE_CASH_DATE","IDEMPOTENCY_KEY_REQUIRED","REPORT_DATE_RANGE_INVALID").contains(code)?HttpStatus.BAD_REQUEST:HttpStatus.CONFLICT,code,"Chứng từ, kỳ kế toán hoặc dữ liệu đã thay đổi; vui lòng kiểm tra lại.");}
 private static AuthException denied(){return new AuthException(HttpStatus.FORBIDDEN,"FINANCE_SCOPE_DENIED","Không có quyền thực hiện trong phạm vi tài chính này.");}
}
